window.__DAILY_CHUNKS__[5] = [{"week":37,"level":"B1","theme":"社会议题与观点辩护","days":[{"day":1,"theme":"词汇 · 社会与议题","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：社会与议题","body":"本周词汇主战场是社会与议题（La société et les débats）。先到 vocab.html#t19 把词表扫一遍，把 <span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span>（不平等）、<span class=\"fr\" data-fr=\"la justice\">la justice</span>（公正）、<span class=\"fr\" data-fr=\"défendre\">défendre</span>（辩护；捍卫）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t19","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5041","level":"B1","skill":"vocab","prompt":"« l'inégalité » 的意思是？","options":["不平等","独立","无能力"],"answer":"不平等","explain":"inégalité 是不平等；indépendance 是独立；incapacité 是无能力。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"vocab","title":"搭配与辨析：un débat / la santé","body":"把 <span class=\"fr\" data-fr=\"un débat\">un débat</span>（辩论）和 <span class=\"fr\" data-fr=\"la santé\">la santé</span>（健康）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t19","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5042","level":"B1","skill":"vocab","prompt":"« défendre » 的意思是？","options":["辩护；捍卫","防御工事","禁止"],"answer":"辩护；捍卫","explain":"défendre 是捍卫、辩护；interdire 是禁止。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"listen","title":"听音辨词：社会与议题","body":"打开 对话页的 d30、d35 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un droit\">un droit</span>（权利）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d30","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il est normal que chacun défende ses intérêts.\">Il est normal que chacun défende ses intérêts.</span>（每个人维护自己的利益是正常的。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：社会与议题 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span> <span class=\"fr\" data-fr=\"la justice\">la justice</span> <span class=\"fr\" data-fr=\"défendre\">défendre</span> <span class=\"fr\" data-fr=\"un débat\">un débat</span> <span class=\"fr\" data-fr=\"la santé\">la santé</span> <span class=\"fr\" data-fr=\"un droit\">un droit</span>。说不出来的词立刻回到 vocab.html#t19 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t19","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]}]},{"day":2,"theme":"语法 · 虚拟式触发词分类","type":"grammar","steps":[{"type":"grammar","title":"语法点：虚拟式触发词分类","body":"【虚拟式触发词分类】表达判断与怀疑的无人称结构（il est normal que、il est regrettable que）后接虚拟式；penser 与 croire 的肯定句用直陈式，否定或疑问句改用虚拟式：Je ne pense pas que ce soit une bonne idée。ne explétif 出现在 avant que、à moins que 之后，本身不表示否定。 例句：<span class=\"fr\" data-fr=\"Il est normal que chacun défende ses intérêts.\">Il est normal que chacun défende ses intérêts.</span>（每个人维护自己的利益是正常的。）；<span class=\"fr\" data-fr=\"Je ne pense pas que ce soit la bonne solution.\">Je ne pense pas que ce soit la bonne solution.</span>（我不认为这是正确的方案。）。对照 grammar-b1b2.html#subj-declencheurs 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#subj-declencheurs","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5041","level":"B1","skill":"grammar","prompt":"« Je ne pense pas que ce ___ une bonne idée. »（être）","options":["soit","est","sera"],"answer":"soit","explain":"penser 的否定句后接虚拟式，être 的形式是 soit。","source":"语法 · 虚拟式 vs 直陈式"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 虚拟式触发词分类 的规则和两个例句，再打开 grammar-b1b2.html#subj-declencheurs 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#subj-declencheurs","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5042","level":"B1","skill":"grammar","prompt":"« Il est normal que chacun ___ ses intérêts. »（défendre）","options":["défende","défend","défendra"],"answer":"défende","explain":"无人称判断结构后接虚拟式。","source":"语法 · 虚拟式触发词"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"在短文里找虚拟式触发词分类","body":"在 grammar-b1b2.html#subj-declencheurs 的例句和章末小测里挑 5 句，圈出所有属于「虚拟式触发词分类」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#subj-declencheurs","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il est normal que chacun défende ses intérêts.\">Il est normal que chacun défende ses intérêts.</span>（每个人维护自己的利益是正常的。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，虚拟式触发词分类 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：虚拟式 vs 直陈式","body":"今天再回 grammar-b1b2.html#subj-vs-indicatif 看一遍 虚拟式 vs 直陈式，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#subj-vs-indicatif","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]}]},{"day":3,"theme":"精听 · 对话页的 d30、d35 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d30、d35 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d30","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5021","level":"B1","skill":"listening","prompt":"圆桌讨论中 « je suis d'accord sur le principe, mais… » 表示？","options":["原则同意但有保留","完全反对","完全同意"],"answer":"原则同意但有保留","explain":"先认可原则再提出保留，是辩论中常见的缓冲表达。","source":"口语 · 辩论"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一场圆桌讨论，整理三位嘉宾的立场。","src":"dialogue.html#d30","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span>（不平等）、<span class=\"fr\" data-fr=\"la justice\">la justice</span>（公正）、<span class=\"fr\" data-fr=\"défendre\">défendre</span>（辩护；捍卫）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t19","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「虚拟式触发词分类 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d30","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 社会议题与观点辩护","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：随机抽一个社会议题，准备 30 秒后陈述 3 分钟并自辩 2 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5011","level":"B1","skill":"speaking","prompt":"即席陈述社会议题时，最稳的框架是？","options":["观点、两个论据、一个让步、结论","只讲个人故事","只反驳对方"],"answer":"观点、两个论据、一个让步、结论","explain":"四段式框架能让即席发言保持结构感。","source":"口语 · 论述结构"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d30、d35 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、虚拟式触发词分类 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d30","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un débat\">un débat</span>（辩论）、<span class=\"fr\" data-fr=\"la santé\">la santé</span>（健康）、<span class=\"fr\" data-fr=\"un droit\">un droit</span>（权利）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t19 再看一遍例句。","src":"vocab.html#t19","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 社会议题与观点辩护","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 2 篇 800 词对立立场的文章。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5021","level":"B1","skill":"reading","prompt":"读对立立场文章时，应重点标注？","options":["双方的核心论点与论据","各自的生词数量","段落长度"],"answer":"双方的核心论点与论据","explain":"标注论点与论据，才能为自己的论证积累素材。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「虚拟式触发词分类」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span>（不平等）、<span class=\"fr\" data-fr=\"la justice\">la justice</span>（公正）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t19","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#subj-declencheurs，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#subj-declencheurs","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「虚拟式触发词分类」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 社会议题与观点辩护","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词「立场、论证、让步、结论」四段文。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5011","level":"B1","skill":"writing","prompt":"四段文里的让步段作用是？","options":["承认对方合理之处再反驳","重复自己的观点","补充例子"],"answer":"承认对方合理之处再反驳","explain":"让步段先承认对方部分合理，再指出其局限，论证更完整。","source":"写作 · 论述结构"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#subj-declencheurs，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#subj-declencheurs","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「虚拟式触发词分类」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span>（不平等）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 社会议题与观点辩护","type":"review","steps":[{"type":"review","title":"本周回顾：社会议题与观点辩护","body":"这一周围绕「社会议题与观点辩护」展开：语法主线是 虚拟式触发词分类，词汇主线是 社会与议题。先用 3 句话口头复述本周学了什么，再打开日历页第 37 周清单逐条核对里程碑。","src":"calendar.html#wk-37","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"语法复盘：虚拟式触发词分类","body":"从 grammar-b1b2.html#subj-declencheurs 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#subj-declencheurs","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"词汇自测：社会与议题","body":"遮住中文看 vocab.html#t19 的 6 个核心词：<span class=\"fr\" data-fr=\"l'inégalité\">l'inégalité</span> <span class=\"fr\" data-fr=\"la justice\">la justice</span> <span class=\"fr\" data-fr=\"défendre\">défendre</span> <span class=\"fr\" data-fr=\"un débat\">un débat</span> <span class=\"fr\" data-fr=\"la santé\">la santé</span> <span class=\"fr\" data-fr=\"un droit\">un droit</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t19","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5043","level":"B1","skill":"vocab","prompt":"« un droit » 的意思是？","options":["权利","笔直的","右边"],"answer":"权利","explain":"droit 可指权利，也可指右边或法律；droite 是右边。","source":"词汇 · 社会"},{"id":"q-vocab-b1-5044","level":"B1","skill":"vocab","prompt":"« un débat » 的意思是？","options":["辩论","债务","下巴"],"answer":"辩论","explain":"débat 是辩论；dette 是债务；menton 是下巴。","source":"词汇 · 社会"},{"ref":"bank:vocab:A2:社会与议题"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d30","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5022","level":"B1","skill":"listening","prompt":"听到 /a mwɛ̃ kə/ 时表示？","options":["除非","因为","尽管"],"answer":"除非","explain":"à moins que 表示除非，后接虚拟式并常带 ne explétif。","source":"语法 · 虚拟式连词"},{"id":"q-read-b1-5022","level":"B1","skill":"reading","prompt":"« ne explétif » 的特点是？","options":["本身不表示否定","表示强烈否定","只能用于口语"],"answer":"本身不表示否定","explain":"ne explétif 出现在 avant que、à moins que 之后，只是书面语习惯，不改变句意。","source":"语法 · 虚拟式"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 虚拟式触发词分类 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#subj-declencheurs 再核对一次。","src":"grammar-b1b2.html#subj-vs-indicatif","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5043","level":"B1","skill":"grammar","prompt":"« Je pense qu'il ___ raison. »（avoir）","options":["a","ait","aura"],"answer":"a","explain":"penser 的肯定句用直陈式，所以用 a。","source":"语法 · 虚拟式 vs 直陈式"},{"id":"q-gram-b1-5044","level":"B1","skill":"grammar","prompt":"下列哪句使用虚拟式是正确的？","options":["Il est regrettable qu'il soit absent.","Il est regrettable qu'il est absent.","Il pense qu'il soit absent."],"answer":"Il est regrettable qu'il soit absent.","explain":"无人称判断结构接虚拟式；penser 的肯定句要用直陈式。","source":"语法 · 虚拟式触发词"},{"ref":"bank:grammar:B1:虚拟式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":38,"level":"B1","theme":"阅读长文与听力笔记法","days":[{"day":1,"theme":"词汇 · 媒体与娱乐","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：媒体与娱乐","body":"媒体与娱乐（Les médias et les loisirs）是这一周要反复见面的主题域。打开 vocab.html#t16，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）、<span class=\"fr\" data-fr=\"une mesure\">une mesure</span>（措施）、<span class=\"fr\" data-fr=\"un constat\">un constat</span>（观察结论）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t16","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5045","level":"B1","skill":"vocab","prompt":"« un enjeu » 的意思是？","options":["关键问题","入口","游戏"],"answer":"关键问题","explain":"enjeu 指关键问题、利害关系；entrée 是入口；jeu 是游戏。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"vocab","title":"搭配与辨析：contester / une note","body":"<span class=\"fr\" data-fr=\"contester\">contester</span>（质疑）与 <span class=\"fr\" data-fr=\"une note\">une note</span>（笔记）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t16","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5046","level":"B1","skill":"vocab","prompt":"« contester » 的意思是？","options":["质疑","确认","测试"],"answer":"质疑","explain":"contester 是质疑、争议；confirmer 是确认；tester 是测试。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"listen","title":"听音辨词：媒体与娱乐","body":"打开 对话页的 d34 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"résumer\">résumer</span>（概括）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d34","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Ce qui m'inquiète, c'est la vitesse du changement.\">Ce qui m'inquiète, c'est la vitesse du changement.</span>（让我担心的是变化的速度。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：媒体与娱乐 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span> <span class=\"fr\" data-fr=\"une mesure\">une mesure</span> <span class=\"fr\" data-fr=\"un constat\">un constat</span> <span class=\"fr\" data-fr=\"contester\">contester</span> <span class=\"fr\" data-fr=\"une note\">une note</span> <span class=\"fr\" data-fr=\"résumer\">résumer</span>。说不出来的词立刻回到 vocab.html#t16 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t16","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]}]},{"day":2,"theme":"语法 · ce qui / ce que / ce dont","type":"grammar","steps":[{"type":"grammar","title":"语法点：ce qui / ce que / ce dont","body":"【ce qui / ce que / ce dont】这一周不学新点，专练「长句解构」：把 25 词以上的长句拆成主干加修饰成分。ce qui / ce que / ce dont 用来指代整句或没有先行词的概念，是长句里最常见的连接件；分词短语与关系从句之间多数情况下可以互相转换。 例句：<span class=\"fr\" data-fr=\"Ce qui m'inquiète, c'est la vitesse du changement.\">Ce qui m'inquiète, c'est la vitesse du changement.</span>（让我担心的是变化的速度。）；<span class=\"fr\" data-fr=\"Les mesures prises par le gouvernement sont contestées.\">Les mesures prises par le gouvernement sont contestées.</span>（政府采取的措施受到质疑。）。对照 grammar-b1b2.html#rel-ce-qui 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#rel-ce-qui","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5045","level":"B1","skill":"grammar","prompt":"« ___ m'inquiète, c'est la vitesse du changement. »","options":["Ce qui","Ce que","Ce dont"],"answer":"Ce qui","explain":"没有先行词且作从句主语，用 ce qui。","source":"语法 · 关系代词"},{"ref":"bank:grammar:B2:ce qui"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#rel-ce-qui 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Ce qui m'inquiète, c'est la vitesse du changement.\">Ce qui m'inquiète, c'est la vitesse du changement.</span>（让我担心的是变化的速度。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#rel-ce-qui","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5046","level":"B1","skill":"grammar","prompt":"「政府采取的措施」应说？","options":["Les mesures prises par le gouvernement","Les mesures prenant par le gouvernement","Les mesures prises le gouvernement"],"answer":"Les mesures prises par le gouvernement","explain":"过去分词短语相当于被动的关系从句，施动者用 par 引出。","source":"语法 · 分词与从句"},{"ref":"bank:grammar:B2:ce qui"}]},{"type":"read","title":"在短文里找ce qui / ce que / ce dont","body":"在 grammar-b1b2.html#rel-ce-qui 的例句和章末小测里挑 5 句，圈出所有属于「ce qui / ce que / ce dont」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#rel-ce-qui","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Ce qui m'inquiète, c'est la vitesse du changement.\">Ce qui m'inquiète, c'est la vitesse du changement.</span>（让我担心的是变化的速度。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，ce qui / ce que / ce dont 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：分词式与从句互转","body":"今天再回 grammar-b1b2.html#participe-relative 看一遍 分词式与从句互转，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#participe-relative","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:ce qui"}]}]},{"day":3,"theme":"精听 · 对话页的 d34 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d34 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d34","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5023","level":"B1","skill":"listening","prompt":"听力笔记最关键的原则是？","options":["只记关键词与逻辑符号","逐字记录","先记翻译"],"answer":"只记关键词与逻辑符号","explain":"速记要记关键词和逻辑关系，逐字记录会跟不上语速。","source":"考试 · 听力策略"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：用考试页的听力速记法，做 3 段 2 分钟音频的笔记复述。","src":"dialogue.html#d34","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）、<span class=\"fr\" data-fr=\"une mesure\">une mesure</span>（措施）、<span class=\"fr\" data-fr=\"un constat\">un constat</span>（观察结论）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t16","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「ce qui / ce que / ce dont 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d34","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 阅读长文与听力笔记法","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：看着自己的听力笔记复述内容，不看原文，5 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5012","level":"B1","skill":"speaking","prompt":"只看笔记复述时，应该？","options":["按笔记的逻辑线展开","背原文句子","先讲结论再补细节"],"answer":"按笔记的逻辑线展开","explain":"笔记提供逻辑骨架，复述要按骨架展开而不是背原句。","source":"口语 · 复述"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d34 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、ce qui / ce que / ce dont 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d34","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"contester\">contester</span>（质疑）、<span class=\"fr\" data-fr=\"une note\">une note</span>（笔记）、<span class=\"fr\" data-fr=\"résumer\">résumer</span>（概括）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t16 再看一遍例句。","src":"vocab.html#t16","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 阅读长文与听力笔记法","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：限时精读 3 篇 800–1000 词文章（10 分钟一篇），做主旨题与细节题。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5023","level":"B1","skill":"reading","prompt":"1000 词长文 12 分钟读完的关键是？","options":["先读结构再定位细节","逐词翻译","反复读首段"],"answer":"先读结构再定位细节","explain":"先建立结构框架，再带着题干回文定位，才能控制时间。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）、<span class=\"fr\" data-fr=\"une mesure\">une mesure</span>（措施）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t16","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#rel-ce-qui，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#rel-ce-qui","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:ce qui"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「ce qui / ce que / ce dont」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 阅读长文与听力笔记法","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词摘要（不许照抄原句，全部改写）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5012","level":"B1","skill":"writing","prompt":"250 词摘要的基本要求是？","options":["全部改写、不照抄原句","尽量引用原句","只写个人评论"],"answer":"全部改写、不照抄原句","explain":"摘要必须改写，照抄会暴露语言能力不足。","source":"写作 · 摘要"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#rel-ce-qui，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#rel-ce-qui","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:ce qui"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「ce qui / ce que / ce dont」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 阅读长文与听力笔记法","type":"review","steps":[{"type":"review","title":"本周回顾：阅读长文与听力笔记法","body":"这一周围绕「阅读长文与听力笔记法」展开：语法主线是 ce qui / ce que / ce dont，词汇主线是 媒体与娱乐。先用 3 句话口头复述本周学了什么，再打开日历页第 38 周清单逐条核对里程碑。","src":"calendar.html#wk-38","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"语法复盘：ce qui / ce que / ce dont","body":"从 grammar-b1b2.html#rel-ce-qui 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#rel-ce-qui","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:ce qui"}]},{"type":"review","title":"词汇自测：媒体与娱乐","body":"遮住中文看 vocab.html#t16 的 6 个核心词：<span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span> <span class=\"fr\" data-fr=\"une mesure\">une mesure</span> <span class=\"fr\" data-fr=\"un constat\">un constat</span> <span class=\"fr\" data-fr=\"contester\">contester</span> <span class=\"fr\" data-fr=\"une note\">une note</span> <span class=\"fr\" data-fr=\"résumer\">résumer</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t16","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5047","level":"B1","skill":"vocab","prompt":"« une mesure » 在政策语境里指？","options":["措施","尺寸","测量"],"answer":"措施","explain":"mesure 在政策语境里指措施，也可指尺寸或测量。","source":"词汇 · 政治"},{"id":"q-vocab-b1-5048","level":"B1","skill":"vocab","prompt":"« résumer » 的意思是？","options":["概括","假设","重新开始"],"answer":"概括","explain":"résumer 是概括、总结；supposer 是假设；reprendre 是重新开始。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A2:媒体与娱乐"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d34","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5024","level":"B1","skill":"listening","prompt":"听到长句时，先抓什么？","options":["主谓宾主干","每个形容词","每个介词短语"],"answer":"主谓宾主干","explain":"长句处理先抓主干，再逐层挂上修饰成分。","source":"考试 · 听力策略"},{"id":"q-read-b1-5024","level":"B1","skill":"reading","prompt":"« ce dont » 的用法是？","options":["代替 de 加整句或缺先行词的概念","代替人作主语","只能代替地点"],"answer":"代替 de 加整句或缺先行词的概念","explain":"ce dont 相当于 de 加先行词，常用于 avoir besoin de、parler de 等结构。","source":"语法 · 关系代词"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 ce qui / ce que / ce dont 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#rel-ce-qui 再核对一次。","src":"grammar-b1b2.html#participe-relative","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5047","level":"B1","skill":"grammar","prompt":"« Ce que je veux, c'est comprendre. » 中 ce que 在从句里作？","options":["直接宾语","主语","状语"],"answer":"直接宾语","explain":"ce que 后面接主语加动词，说明它在从句里作直接宾语。","source":"语法 · 关系代词"},{"id":"q-gram-b1-5048","level":"B1","skill":"grammar","prompt":"分词短语与关系从句的关系是？","options":["多数情况下可以互相转换","完全不能转换","只能在口语里转换"],"answer":"多数情况下可以互相转换","explain":"现在分词常可换成 qui 从句，过去分词短语常可换成被动的 que 从句。","source":"语法 · 分词与从句"},{"ref":"bank:grammar:B2:ce qui"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":39,"level":"B1","theme":"写作攻坚：200–250 词论述与正式信函","days":[{"day":1,"theme":"词汇 · 抽象概念与逻辑","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：抽象概念与逻辑","body":"本周词汇主战场是抽象概念与逻辑（Les notions abstraites et la logique）。先到 vocab.html#t24 把词表扫一遍，把 <span class=\"fr\" data-fr=\"constater\">constater</span>（观察到）、<span class=\"fr\" data-fr=\"sembler\">sembler</span>（似乎）、<span class=\"fr\" data-fr=\"une constatation\">une constatation</span>（观察结论）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t24","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5049","level":"B1","skill":"vocab","prompt":"« constater » 的意思是？","options":["观察到","建造","咨询"],"answer":"观察到","explain":"constater 是观察到、确认事实；construire 是建造；consulter 是咨询。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"vocab","title":"搭配与辨析：un brouillon / reformuler","body":"把 <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span>（草稿）和 <span class=\"fr\" data-fr=\"reformuler\">reformuler</span>（改写）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t24","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5050","level":"B1","skill":"vocab","prompt":"« un brouillon » 的意思是？","options":["草稿","画笔","混乱"],"answer":"草稿","explain":"brouillon 是草稿；pinceau 是画笔；désordre 是混乱。","source":"词汇 · 写作"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"listen","title":"听音辨词：抽象概念与逻辑","body":"打开 对话页的 d31 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"une relecture\">une relecture</span>（通读检查）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d31","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"On constate que les habitudes ont changé.\">On constate que les habitudes ont changé.</span>（可以看到，习惯已经改变。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：抽象概念与逻辑 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"constater\">constater</span> <span class=\"fr\" data-fr=\"sembler\">sembler</span> <span class=\"fr\" data-fr=\"une constatation\">une constatation</span> <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span> <span class=\"fr\" data-fr=\"reformuler\">reformuler</span> <span class=\"fr\" data-fr=\"une relecture\">une relecture</span>。说不出来的词立刻回到 vocab.html#t24 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t24","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]}]},{"day":2,"theme":"语法 · 书面语体特征","type":"grammar","steps":[{"type":"grammar","title":"语法点：书面语体特征","body":"【书面语体特征】书面语体的五条特征是名词化、无人称结构、逻辑显性化、分词结构与词汇升级。无人称结构（il semble que、on constate que）能让论述显得客观；强调结构（C'est… qui / que、Ce qui compte, c'est…）用来点题。写作前先列提纲，能显著提高结构分。 例句：<span class=\"fr\" data-fr=\"On constate que les habitudes ont changé.\">On constate que les habitudes ont changé.</span>（可以看到，习惯已经改变。）；<span class=\"fr\" data-fr=\"Ce qui compte, c'est la régularité.\">Ce qui compte, c'est la régularité.</span>（重要的是坚持。）。对照 grammar-b1b2.html#nom-style 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#nom-style","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5049","level":"B1","skill":"grammar","prompt":"书面语中表达「可以看到」应用？","options":["On constate que…","On voit bien.","Je vois."],"answer":"On constate que…","explain":"泛称与无人称结构让论述显得客观，是书面语的标志。","source":"语法 · 书面语体"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 书面语体特征 的规则和两个例句，再打开 grammar-b1b2.html#nom-style 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#nom-style","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5050","level":"B1","skill":"grammar","prompt":"点题结构「重要的是……」应说？","options":["Ce qui compte, c'est…","C'est important.","Ça compte beaucoup."],"answer":"Ce qui compte, c'est…","explain":"Ce qui… c'est 是议论文里常用的点题结构。","source":"语法 · 强调结构"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"read","title":"在短文里找书面语体特征","body":"在 grammar-b1b2.html#nom-style 的例句和章末小测里挑 5 句，圈出所有属于「书面语体特征」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#nom-style","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"On constate que les habitudes ont changé.\">On constate que les habitudes ont changé.</span>（可以看到，习惯已经改变。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，书面语体特征 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：强调结构 c'est… qui / que","body":"今天再回 grammar-b1b2.html#mer-cest 看一遍 强调结构 c'est… qui / que，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#mer-cest","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:书面语体"}]}]},{"day":3,"theme":"精听 · 对话页的 d31 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d31 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d31","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5025","level":"B1","skill":"listening","prompt":"朗读自己的文章时，最容易发现的问题是？","options":["句子过长、逻辑不清","标点符号","字数不够"],"answer":"句子过长、逻辑不清","explain":"朗读能让书面语里的长句与断裂逻辑变得明显。","source":"写作 · 自查方法"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：本周不安排泛听，改为朗读自己的文章并录音自检。","src":"dialogue.html#d31","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"constater\">constater</span>（观察到）、<span class=\"fr\" data-fr=\"sembler\">sembler</span>（似乎）、<span class=\"fr\" data-fr=\"une constatation\">une constatation</span>（观察结论）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t24","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「书面语体特征 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d31","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 200–250 词论述与正式信函","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：把写的文章讲出来，做 3 分钟脱稿陈述。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5013","level":"B1","skill":"speaking","prompt":"脱稿讲自己的文章时，应该？","options":["保持原来的论证顺序","完全重新组织","只讲结论"],"answer":"保持原来的论证顺序","explain":"脱稿陈述要沿用文章结构，才能检验逻辑是否真的清楚。","source":"口语 · 陈述"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d31 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、书面语体特征 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d31","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span>（草稿）、<span class=\"fr\" data-fr=\"reformuler\">reformuler</span>（改写）、<span class=\"fr\" data-fr=\"une relecture\">une relecture</span>（通读检查）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t24 再看一遍例句。","src":"vocab.html#t24","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 200–250 词论述与正式信函","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：研读考试页三档范文（13、17、22 分），逐段标注差别。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5025","level":"B1","skill":"reading","prompt":"对比三档范文时，最值得研究的是？","options":["17 分与 22 分之间的差距","13 分范文的用词","范文的字数"],"answer":"17 分与 22 分之间的差距","explain":"中间档与高分档的差距最能告诉你下一步该改什么。","source":"考试 · 范文研读"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「书面语体特征」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"constater\">constater</span>（观察到）、<span class=\"fr\" data-fr=\"sembler\">sembler</span>（似乎）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t24","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#nom-style，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#nom-style","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「书面语体特征」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 200–250 词论述与正式信函","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 2 篇完整 250 词文章（一篇立场论述、一封正式信函），各改两稿。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5013","level":"B1","skill":"writing","prompt":"改第二稿时，最优先处理的是？","options":["结构与逻辑问题","标点细节","字体格式"],"answer":"结构与逻辑问题","explain":"先解决结构与逻辑，再打磨词汇与细节，性价比最高。","source":"写作 · 改稿策略"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#nom-style，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#nom-style","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「书面语体特征」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"constater\">constater</span>（观察到）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 200–250 词论述与正式信函","type":"review","steps":[{"type":"review","title":"本周回顾：写作攻坚：200–250 词论述与正式信函","body":"这一周围绕「写作攻坚：200–250 词论述与正式信函」展开：语法主线是 书面语体特征，词汇主线是 抽象概念与逻辑。先用 3 句话口头复述本周学了什么，再打开日历页第 39 周清单逐条核对里程碑。","src":"calendar.html#wk-39","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"语法复盘：书面语体特征","body":"从 grammar-b1b2.html#nom-style 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#nom-style","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:书面语体"}]},{"type":"review","title":"词汇自测：抽象概念与逻辑","body":"遮住中文看 vocab.html#t24 的 6 个核心词：<span class=\"fr\" data-fr=\"constater\">constater</span> <span class=\"fr\" data-fr=\"sembler\">sembler</span> <span class=\"fr\" data-fr=\"une constatation\">une constatation</span> <span class=\"fr\" data-fr=\"un brouillon\">un brouillon</span> <span class=\"fr\" data-fr=\"reformuler\">reformuler</span> <span class=\"fr\" data-fr=\"une relecture\">une relecture</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t24","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5051","level":"B1","skill":"vocab","prompt":"« reformuler » 的意思是？","options":["改写","复制","朗读"],"answer":"改写","explain":"reformuler 是改写、重新表述；copier 是复制。","source":"词汇 · 写作"},{"id":"q-vocab-b1-5052","level":"B1","skill":"vocab","prompt":"« une relecture » 的意思是？","options":["通读检查","重读的习惯","讲座"],"answer":"通读检查","explain":"relecture 指写完后的通读检查，是写作流程的最后一步。","source":"词汇 · 写作"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d31","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5026","level":"B1","skill":"listening","prompt":"听自己的录音时，最应该关注？","options":["停顿位置与连接词","音色","音量"],"answer":"停顿位置与连接词","explain":"停顿与连接词反映思维的连贯程度，比音色重要得多。","source":"口语 · 自评"},{"id":"q-read-b1-5026","level":"B1","skill":"reading","prompt":"名词化在书面语里的作用是？","options":["压缩句子、提高语域","让句子更长","增加感情色彩"],"answer":"压缩句子、提高语域","explain":"名词化把动词句压缩为名词短语，是书面语压缩信息的主要手段。","source":"语法 · 书面语体"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 书面语体特征 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#nom-style 再核对一次。","src":"grammar-b1b2.html#mer-cest","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5051","level":"B1","skill":"grammar","prompt":"« Il semble que ce ___ difficile. »（être）","options":["soit","est","sera"],"answer":"soit","explain":"il semble que 后接虚拟式，être 的形式是 soit。","source":"语法 · 虚拟式"},{"id":"q-gram-b1-5052","level":"B1","skill":"grammar","prompt":"下列哪句最符合书面语体？","options":["La hausse des prix inquiète les ménages.","Les prix montent et ça inquiète les gens.","Les prix, ça monte."],"answer":"La hausse des prix inquiète les ménages.","explain":"名词化加抽象主语是典型的书面语体，后两句偏口语。","source":"语法 · 书面语体"},{"ref":"bank:grammar:B2:书面语体"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":40,"level":"B1","theme":"B1 出口测：全项模拟与 B2 过渡（词汇 2500）","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"高频动词与万能表达（Les verbes fréquents et les expressions utiles）是这一周要反复见面的主题域。打开 vocab.html#t25，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span>（评估）、<span class=\"fr\" data-fr=\"une lacune\">une lacune</span>（缺项；漏洞）、<span class=\"fr\" data-fr=\"un seuil\">un seuil</span>（门槛）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b1-5053","level":"B1","skill":"vocab","prompt":"« une lacune » 的意思是？","options":["缺项；漏洞","湖泊","运气"],"answer":"缺项；漏洞","explain":"lacune 指知识或结构上的缺项；lac 是湖。","source":"词汇 · 评估"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：consolider / un axe","body":"<span class=\"fr\" data-fr=\"consolider\">consolider</span>（巩固）与 <span class=\"fr\" data-fr=\"un axe\">un axe</span>（方向；轴线）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b1-5054","level":"B1","skill":"vocab","prompt":"« consolider » 的意思是？","options":["巩固","安慰","建造"],"answer":"巩固","explain":"consolider 是巩固、加强；consoler 是安慰；construire 是建造。","source":"词汇 · 学习"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d25 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"viser\">viser</span>（瞄准；旨在）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d25","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il a expliqué qu'il avait changé d'avis.\">Il a expliqué qu'il avait changé d'avis.</span>（他解释说自己改变了主意。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span> <span class=\"fr\" data-fr=\"une lacune\">une lacune</span> <span class=\"fr\" data-fr=\"un seuil\">un seuil</span> <span class=\"fr\" data-fr=\"consolider\">consolider</span> <span class=\"fr\" data-fr=\"un axe\">un axe</span> <span class=\"fr\" data-fr=\"viser\">viser</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · 时态配合","type":"grammar","steps":[{"type":"grammar","title":"语法点：时态配合","body":"【时态配合】这一周做 B1 全项模拟，并用 B2 模拟卷试做一套，允许低分，重点在找出差距。语法上把全年语法点做一张掌握度自评表（0–5 分），低于 3 分的排进第 41–46 周补强；词汇目标 2500 词，主动可调用词不少于 1200。 例句：<span class=\"fr\" data-fr=\"Il a expliqué qu'il avait changé d'avis.\">Il a expliqué qu'il avait changé d'avis.</span>（他解释说自己改变了主意。）；<span class=\"fr\" data-fr=\"Je ne crois pas que ce soit suffisant.\">Je ne crois pas que ce soit suffisant.</span>（我不认为这已经足够。）。对照 grammar-b1b2.html#concordance 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#concordance","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b1-5053","level":"B1","skill":"grammar","prompt":"「他解释说自己改变了主意」应说？","options":["Il a expliqué qu'il avait changé d'avis.","Il a expliqué qu'il a changé d'avis.","Il explique qu'il avait changé d'avis."],"answer":"Il a expliqué qu'il avait changé d'avis.","explain":"主句过去时，从句的复合过去时要推移为愈过去时。","source":"语法 · 时态配合"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#concordance 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Il a expliqué qu'il avait changé d'avis.\">Il a expliqué qu'il avait changé d'avis.</span>（他解释说自己改变了主意。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#concordance","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b1-5054","level":"B1","skill":"grammar","prompt":"「我不认为这已经足够」应说？","options":["Je ne crois pas que ce soit suffisant.","Je ne crois pas que c'est suffisant.","Je crois que ce soit suffisant."],"answer":"Je ne crois pas que ce soit suffisant.","explain":"croire 的否定句后接虚拟式，肯定句才用直陈式。","source":"语法 · 虚拟式 vs 直陈式"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"read","title":"在短文里找时态配合","body":"在 grammar-b1b2.html#concordance 的例句和章末小测里挑 5 句，圈出所有属于「时态配合」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#concordance","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il a expliqué qu'il avait changé d'avis.\">Il a expliqué qu'il avait changé d'avis.</span>（他解释说自己改变了主意。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，时态配合 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"语法点巩固：虚拟式","body":"今天再回 grammar-b1b2.html#subjonctif 看一遍 虚拟式，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#subjonctif","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:时态配合"}]}]},{"day":3,"theme":"精听 · 对话页的 d25 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d25 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d25","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b1-5027","level":"B1","skill":"listening","prompt":"从 B1 到 B2 的听力差距主要体现在？","options":["语速、信息密度与隐含意义","音质","口音种类"],"answer":"语速、信息密度与隐含意义","explain":"B2 听力在语速、信息密度以及言外之意上的要求明显提高。","source":"考试 · 听力策略"},{"ref":"bank:listening:B1:听力"}],"exam":"exam:listening:B1:预约看房"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：用 B1 听力原题限时做一遍，再用 B2 样题试一遍，比较难度差。","src":"dialogue.html#d25","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span>（评估）、<span class=\"fr\" data-fr=\"une lacune\">une lacune</span>（缺项；漏洞）、<span class=\"fr\" data-fr=\"un seuil\">un seuil</span>（门槛）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「时态配合 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d25","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B1:听力"}]}]},{"day":4,"theme":"口语 · 全项模拟与 B2 过渡（词汇 2500）","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：录 5 分钟陈述，与第 26 周录音对比，量化流利度与错误数。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b1-5014","level":"B1","skill":"speaking","prompt":"量化口语进步时，最该记录的两个指标是？","options":["错误数与流利度","音量与音色","录音时长"],"answer":"错误数与流利度","explain":"错误数与流利度能直观反映能力变化，音色音量与能力无关。","source":"口语 · 自评"},{"ref":"bank:speaking:B1:口语"}],"exam":"exam:speaking:B1:家庭作业"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d25 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、时态配合 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d25","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"consolider\">consolider</span>（巩固）、<span class=\"fr\" data-fr=\"un axe\">un axe</span>（方向；轴线）、<span class=\"fr\" data-fr=\"viser\">viser</span>（瞄准；旨在）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":5,"theme":"精读 · 全项模拟与 B2 过渡（词汇 2500）","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 B2 长文（限时 15 分钟），记录生词密度与理解率。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b1-5027","level":"B1","skill":"reading","prompt":"读 B2 长文时，「生词密度」指标的作用是？","options":["判断材料难度是否合适","统计语法错误","衡量阅读速度"],"answer":"判断材料难度是否合适","explain":"生词密度可以用来挑选难度合适的阅读材料。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B1:阅读"}],"exam":"exam:reading:B1:青少年与屏幕"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span>（评估）、<span class=\"fr\" data-fr=\"une lacune\">une lacune</span>（缺项；漏洞）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#concordance，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#concordance","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「时态配合」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B1:写作"}]}]},{"day":6,"theme":"写作 · 全项模拟与 B2 过渡（词汇 2500）","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词文章，逐项按 B2 评分表打分，列出 3 个最需要补的项。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b1-5014","level":"B1","skill":"writing","prompt":"对照 B2 评分表时，最该关注的差距是？","options":["结构、词汇多样性与语法准确度","字数","书写美观度"],"answer":"结构、词汇多样性与语法准确度","explain":"B2 评分的核心是结构、词汇与语法的综合表现。","source":"写作 · 评分标准"},{"ref":"bank:writing:B1:写作"}],"exam":"exam:writing:B1:廉价航空"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#concordance，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#concordance","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「时态配合」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span>（评估）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B1:口语"}]}]},{"day":7,"theme":"复盘 · 全项模拟与 B2 过渡（词汇 2500）","type":"review","steps":[{"type":"review","title":"本周回顾：B1 出口测：全项模拟与 B2 过渡（词汇 2500）","body":"这一周围绕「B1 出口测：全项模拟与 B2 过渡（词汇 2500）」展开：语法主线是 时态配合，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 40 周清单逐条核对里程碑。","src":"calendar.html#wk-40","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：时态配合","body":"从 grammar-b1b2.html#concordance 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#concordance","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"une évaluation\">une évaluation</span> <span class=\"fr\" data-fr=\"une lacune\">une lacune</span> <span class=\"fr\" data-fr=\"un seuil\">un seuil</span> <span class=\"fr\" data-fr=\"consolider\">consolider</span> <span class=\"fr\" data-fr=\"un axe\">un axe</span> <span class=\"fr\" data-fr=\"viser\">viser</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b1-5055","level":"B1","skill":"vocab","prompt":"« viser » 的意思是？","options":["瞄准；旨在","签证","可见的"],"answer":"瞄准；旨在","explain":"viser 表示瞄准、旨在；visa 是签证；visible 是可见的。","source":"词汇 · 高频动词"},{"id":"q-vocab-b1-5056","level":"B1","skill":"vocab","prompt":"« un axe » 的意思是？","options":["方向；轴线","斧头","建筑"],"answer":"方向；轴线","explain":"axe 指方向、轴线；hache 是斧头。","source":"词汇 · 抽象概念"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d25","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b1-5028","level":"B1","skill":"listening","prompt":"B2 样题试做后最有价值的动作是？","options":["逐项分析失分原因","只记总分","立即重做一遍"],"answer":"逐项分析失分原因","explain":"分析失分原因才能把差距转化成具体训练计划。","source":"考试 · 复盘方法"},{"id":"q-read-b1-5028","level":"B1","skill":"reading","prompt":"自评分数低于 3 分时应该？","options":["排进第 41–46 周补强","直接学习 B2 新内容","放弃该语法点"],"answer":"排进第 41–46 周补强","explain":"课程表的策略是把低于 3 分的语法点排进第 41–46 周继续补强。","source":"学习 · 规划"},{"ref":"bank:listening:B1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 时态配合 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#concordance 再核对一次。","src":"grammar-b1b2.html#subjonctif","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b1-5055","level":"B1","skill":"grammar","prompt":"主句过去时，从句表示「同时发生」的动作该用什么时态？","options":["未完成过去时","现在时","简单将来时"],"answer":"未完成过去时","explain":"时态配合规则：主句过去时，从句同时发生的动作变未完成过去时。","source":"语法 · 时态配合"},{"id":"q-gram-b1-5056","level":"B1","skill":"grammar","prompt":"下列哪句是正确的？","options":["Il faut que nous fassions attention.","Il faut que nous faisons attention.","Il faut que nous ferons attention."],"answer":"Il faut que nous fassions attention.","explain":"il faut que 后接虚拟式，faire 的 nous 虚拟式是 fassions。","source":"语法 · 虚拟式变位"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B1:写作"}]}]}]},{"week":41,"level":"B2","theme":"时态配合与复杂关系从句","days":[{"day":1,"theme":"词汇 · 政治与法律","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：政治与法律","body":"本周词汇主战场是政治与法律（La politique et le droit）。先到 vocab.html#t21 把词表扫一遍，把 <span class=\"fr\" data-fr=\"aboutir\">aboutir</span>（成功；达成）、<span class=\"fr\" data-fr=\"un rapport\">un rapport</span>（报告）、<span class=\"fr\" data-fr=\"confidentiel\">confidentiel</span>（保密的）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t21","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5001","level":"B2","skill":"vocab","prompt":"« aboutir » 的意思是？","options":["成功；达成","结束演讲","到达终点线"],"answer":"成功；达成","explain":"aboutir 表示最终达成结果，aboutir à 引出结果。","source":"词汇 · 政治"},{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"vocab","title":"搭配与辨析：un député / la législation","body":"把 <span class=\"fr\" data-fr=\"un député\">un député</span>（议员）和 <span class=\"fr\" data-fr=\"la législation\">la législation</span>（立法；法规）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t21","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5002","level":"B2","skill":"vocab","prompt":"« confidentiel » 的意思是？","options":["保密的","自信的","依靠的"],"answer":"保密的","explain":"confidentiel 是保密的；confiant 是自信的；dépendant 是依赖的。","source":"词汇 · 政治"},{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"listen","title":"听音辨词：政治与法律","body":"打开 对话页的 d35 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un débat public\">un débat public</span>（公共辩论）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d35","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Il pensait que le projet aboutirait.\">Il pensait que le projet aboutirait.</span>（他当时认为这个项目会成功。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：政治与法律 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"aboutir\">aboutir</span> <span class=\"fr\" data-fr=\"un rapport\">un rapport</span> <span class=\"fr\" data-fr=\"confidentiel\">confidentiel</span> <span class=\"fr\" data-fr=\"un député\">un député</span> <span class=\"fr\" data-fr=\"la législation\">la législation</span> <span class=\"fr\" data-fr=\"un débat public\">un débat public</span>。说不出来的词立刻回到 vocab.html#t21 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t21","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:政治与法律"}]}]},{"day":2,"theme":"语法 · 时态配合 concordance des temps","type":"grammar","steps":[{"type":"grammar","title":"语法点：时态配合 concordance des temps","body":"【时态配合 concordance des temps】时态配合的核心是：主句用过去时，从句表示同时动作用未完成过去时，表示先时用愈过去时，表示后时用条件式。关系代词里 dont 代替 de 加先行词，可作动词、名词、形容词与数量补语；lequel 系列用在介词后，à 与 de 要和它缩合成 auquel、duquel。 例句：<span class=\"fr\" data-fr=\"Il pensait que le projet aboutirait.\">Il pensait que le projet aboutirait.</span>（他当时认为这个项目会成功。）；<span class=\"fr\" data-fr=\"Le rapport dont je parle est confidentiel.\">Le rapport dont je parle est confidentiel.</span>（我谈到的这份报告是保密的。）。对照 grammar-b1b2.html#concordance 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#concordance","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5001","level":"B2","skill":"grammar","prompt":"主句过去时，从句表示「后时」的动作该用什么？","options":["条件式","简单将来时","现在时"],"answer":"条件式","explain":"时态配合里，主句过去时、从句后时动作用条件式。","source":"语法 · 时态配合"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 时态配合 concordance des temps 的规则和两个例句，再打开 grammar-b1b2.html#concordance 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#concordance","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5002","level":"B2","skill":"grammar","prompt":"« Le rapport ___ je parle est confidentiel. »","options":["dont","que","auquel"],"answer":"dont","explain":"parler de 需要 de，用关系代词 dont。","source":"语法 · 关系代词"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"read","title":"在短文里找时态配合 concordance des temps","body":"在 grammar-b1b2.html#concordance 的例句和章末小测里挑 5 句，圈出所有属于「时态配合 concordance des temps」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#concordance","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Il pensait que le projet aboutirait.\">Il pensait que le projet aboutirait.</span>（他当时认为这个项目会成功。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，时态配合 concordance des temps 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：关系代词 dont","body":"今天再回 grammar-b1b2.html#rel-dont 看一遍 关系代词 dont，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#rel-dont","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B1:时态配合"}]}]},{"day":3,"theme":"精听 · 对话页的 d35 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d35 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d35","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5001","level":"B2","skill":"listening","prompt":"听到 « il a dit qu'il viendrait » 中 viendrait 表示？","options":["从句动作在主句之后","从句动作在主句之前","从句动作与主句同时"],"answer":"从句动作在主句之后","explain":"条件式在这里表示相对于过去主句的将来。","source":"语法 · 时态配合"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:四天工作制"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段长访谈，标记所有「过去时主句加从属句」的结构。","src":"dialogue.html#d35","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"aboutir\">aboutir</span>（成功；达成）、<span class=\"fr\" data-fr=\"un rapport\">un rapport</span>（报告）、<span class=\"fr\" data-fr=\"confidentiel\">confidentiel</span>（保密的）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t21","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「时态配合 concordance des temps 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d35","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 时态配合与复杂关系从句","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用 dont / auquel / ce dont 各造 4 句，内容用你的真实信息。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5001","level":"B2","skill":"speaking","prompt":"用 dont 造句时要注意？","options":["动词或名词本身需要 de","先行词必须是地点","只能指人"],"answer":"动词或名词本身需要 de","explain":"dont 代替 de 加先行词，因此从句里的动词或名词必须本来需要 de。","source":"语法 · 关系代词"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:禁止私家车"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d35 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、时态配合 concordance des temps 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d35","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un député\">un député</span>（议员）、<span class=\"fr\" data-fr=\"la législation\">la législation</span>（立法；法规）、<span class=\"fr\" data-fr=\"un débat public\">un débat public</span>（公共辩论）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t21 再看一遍例句。","src":"vocab.html#t21","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 时态配合与复杂关系从句","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读一篇 1000 词政治评论，画出所有代词与从句的关系。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5001","level":"B2","skill":"reading","prompt":"读政治评论时，画代词与从句关系的作用是？","options":["看清谁对谁做了什么","统计生词","判断作者年龄"],"answer":"看清谁对谁做了什么","explain":"长评论里的代词与从句链决定语义指向，画关系图能避免误读。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:远程办公"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「时态配合 concordance des temps」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"aboutir\">aboutir</span>（成功；达成）、<span class=\"fr\" data-fr=\"un rapport\">un rapport</span>（报告）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t21","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#concordance，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#concordance","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「时态配合 concordance des temps」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 时态配合与复杂关系从句","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词评论，至少 6 个关系从句，其中 2 个用 dont。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5001","level":"B2","skill":"writing","prompt":"「我谈到的那个问题」应说？","options":["le problème dont je parle","le problème que je parle","le problème auquel je parle"],"answer":"le problème dont je parle","explain":"parler de 需要 de，用 dont 替换。","source":"语法 · 关系代词"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:免费停车"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#concordance，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#concordance","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「时态配合 concordance des temps」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"aboutir\">aboutir</span>（成功；达成）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 时态配合与复杂关系从句","type":"review","steps":[{"type":"review","title":"本周回顾：时态配合与复杂关系从句","body":"这一周围绕「时态配合与复杂关系从句」展开：语法主线是 时态配合 concordance des temps，词汇主线是 政治与法律。先用 3 句话口头复述本周学了什么，再打开日历页第 41 周清单逐条核对里程碑。","src":"calendar.html#wk-41","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"review","title":"语法复盘：时态配合 concordance des temps","body":"从 grammar-b1b2.html#concordance 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#concordance","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B1:时态配合"}]},{"type":"review","title":"词汇自测：政治与法律","body":"遮住中文看 vocab.html#t21 的 6 个核心词：<span class=\"fr\" data-fr=\"aboutir\">aboutir</span> <span class=\"fr\" data-fr=\"un rapport\">un rapport</span> <span class=\"fr\" data-fr=\"confidentiel\">confidentiel</span> <span class=\"fr\" data-fr=\"un député\">un député</span> <span class=\"fr\" data-fr=\"la législation\">la législation</span> <span class=\"fr\" data-fr=\"un débat public\">un débat public</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t21","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5003","level":"B2","skill":"vocab","prompt":"« un député » 的意思是？","options":["议员","代表处","部门"],"answer":"议员","explain":"député 是议员；députation 是议员职务；département 是省或部门。","source":"词汇 · 政治"},{"id":"q-vocab-b2-5004","level":"B2","skill":"vocab","prompt":"« la législation » 的意思是？","options":["立法；法规","合法化","立法者"],"answer":"立法；法规","explain":"législation 指法规体系；légalisation 是合法化；législateur 是立法者。","source":"词汇 · 法律"},{"ref":"bank:vocab:A2:政治与法律"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d35","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5002","level":"B2","skill":"listening","prompt":"听到 « auquel » 时应判断其为？","options":["à 加 lequel 的缩合","de 加 lequel 的缩合","介词加 qui"],"answer":"à 加 lequel 的缩合","explain":"auquel 是 à 与 lequel 的缩合形式；duquel 才是 de 与 lequel 的缩合。","source":"语法 · 关系代词"},{"id":"q-read-b2-5002","level":"B2","skill":"reading","prompt":"« dont » 可以作哪类补语？","options":["动词、名词、形容词与数量补语","只能作主语","只能作直接宾语"],"answer":"动词、名词、形容词与数量补语","explain":"dont 的用法覆盖动词搭配、名词补语、形容词补语与数量表达。","source":"语法 · 关系代词"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 时态配合 concordance des temps 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#concordance 再核对一次。","src":"grammar-b1b2.html#rel-dont","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5003","level":"B2","skill":"grammar","prompt":"« Le projet ___ il travaille est ambitieux. »","options":["auquel","dont","que"],"answer":"auquel","explain":"travailler à 需要 à，介词加 lequel 缩合为 auquel。","source":"语法 · 关系代词"},{"id":"q-gram-b2-5004","level":"B2","skill":"grammar","prompt":"「我以为你已经离开了」应说？","options":["Je pensais que tu étais déjà parti.","Je pensais que tu es déjà parti.","Je pensais que tu seras déjà parti."],"answer":"Je pensais que tu étais déjà parti.","explain":"主句过去时，从句表示先时的动作用愈过去时。","source":"语法 · 时态配合"},{"ref":"bank:grammar:B1:时态配合"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":42,"level":"B2","theme":"B2 论述入门：立场文结构与论点库","days":[{"day":1,"theme":"词汇 · 经济与金融","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：经济与金融","body":"经济与金融（L'économie et la finance）是这一周要反复见面的主题域。打开 vocab.html#t22，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"indéniable\">indéniable</span>（不可否认的）、<span class=\"fr\" data-fr=\"une solution\">une solution</span>（解决方案）、<span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t22","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5005","level":"B2","skill":"vocab","prompt":"« indéniable » 的意思是？","options":["不可否认的","无法解释的","不可分割的"],"answer":"不可否认的","explain":"indéniable 是不可否认的；inexplicable 是无法解释的；indivisible 是不可分割的。","source":"词汇 · 论述"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"vocab","title":"搭配与辨析：un marché / la croissance","body":"<span class=\"fr\" data-fr=\"un marché\">un marché</span>（市场）与 <span class=\"fr\" data-fr=\"la croissance\">la croissance</span>（增长）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t22","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5006","level":"B2","skill":"vocab","prompt":"« la croissance » 的意思是？","options":["增长","十字架","创造"],"answer":"增长","explain":"croissance 是增长；croix 是十字架；création 是创造。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"listen","title":"听音辨词：经济与金融","body":"打开 对话页的 d35 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un investissement\">un investissement</span>（投资）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d35","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Force est de constater que les inégalités persistent.\">Force est de constater que les inégalités persistent.</span>（不得不承认，不平等依然存在。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：经济与金融 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"indéniable\">indéniable</span> <span class=\"fr\" data-fr=\"une solution\">une solution</span> <span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span> <span class=\"fr\" data-fr=\"un marché\">un marché</span> <span class=\"fr\" data-fr=\"la croissance\">la croissance</span> <span class=\"fr\" data-fr=\"un investissement\">un investissement</span>。说不出来的词立刻回到 vocab.html#t22 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t22","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]}]},{"day":2,"theme":"语法 · B2 高频固定搭配","type":"grammar","steps":[{"type":"grammar","title":"语法点：B2 高频固定搭配","body":"【B2 高频固定搭配】B2 立场文要有清晰的引言、两到三个论点、一个反方段与结论。客观化表达用 il est indéniable que、force est de constater que、on peut soutenir que；点题用 Ce qui… c'est 结构。整篇必须使用同一语域，不能口语书面混杂。 例句：<span class=\"fr\" data-fr=\"Force est de constater que les inégalités persistent.\">Force est de constater que les inégalités persistent.</span>（不得不承认，不平等依然存在。）；<span class=\"fr\" data-fr=\"Ce qui importe, c'est de proposer des solutions concrètes.\">Ce qui importe, c'est de proposer des solutions concrètes.</span>（重要的是提出具体方案。）。对照 grammar-b1b2.html#expressions-b2 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#expressions-b2","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5005","level":"B2","skill":"grammar","prompt":"客观化表达「不得不承认」应说？","options":["Force est de constater que…","Je dois dire que…","Moi je pense que…"],"answer":"Force est de constater que…","explain":"force est de constater que 是书面语中的客观化表达。","source":"语法 · 书面语体"},{"ref":"bank:grammar:B2:论述"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#expressions-b2 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Force est de constater que les inégalités persistent.\">Force est de constater que les inégalités persistent.</span>（不得不承认，不平等依然存在。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#expressions-b2","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5006","level":"B2","skill":"grammar","prompt":"「重要的是提出方案」应说？","options":["Ce qui importe, c'est de proposer des solutions.","C'est important proposer des solutions.","Il est important que proposer."],"answer":"Ce qui importe, c'est de proposer des solutions.","explain":"Ce qui… c'est 是点题结构，后面接不定式或名词短语。","source":"语法 · 强调结构"},{"ref":"bank:grammar:B2:论述"}]},{"type":"read","title":"在短文里找B2 高频固定搭配","body":"在 grammar-b1b2.html#expressions-b2 的例句和章末小测里挑 5 句，圈出所有属于「B2 高频固定搭配」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#expressions-b2","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Force est de constater que les inégalités persistent.\">Force est de constater que les inégalités persistent.</span>（不得不承认，不平等依然存在。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，B2 高频固定搭配 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：ce qui / ce que … c'est","body":"今天再回 grammar-b1b2.html#mer-cequi-cest 看一遍 ce qui / ce que … c'est，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#mer-cequi-cest","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:论述"}]}]},{"day":3,"theme":"精听 · 对话页的 d35 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d35 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d35","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5003","level":"B2","skill":"listening","prompt":"为辩论建三列表时，三列分别是？","options":["论点、论据、例证","时间、地点、人物","赞同、反对、中立"],"answer":"论点、论据、例证","explain":"论点、论据、例证的结构能把听到的内容直接转成写作素材。","source":"考试 · 听力策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:一次性塑料"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听 2 场辩论，为每场建一个「论点、论据、例证」三列表。","src":"dialogue.html#d35","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"indéniable\">indéniable</span>（不可否认的）、<span class=\"fr\" data-fr=\"une solution\">une solution</span>（解决方案）、<span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span>（关键问题）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t22","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「B2 高频固定搭配 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d35","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 立场文结构与论点库","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：任选议题做「正方 3 分钟、反方 3 分钟」双向陈述。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5002","level":"B2","skill":"speaking","prompt":"做双向陈述时，最大的挑战是？","options":["为相反立场找到论据","记住自己的观点","控制音量"],"answer":"为相反立场找到论据","explain":"双向陈述能暴露论据储备是否充足，迫使你为反方寻找理由。","source":"口语 · 辩论"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:远程办公"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d35 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、B2 高频固定搭配 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d35","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un marché\">un marché</span>（市场）、<span class=\"fr\" data-fr=\"la croissance\">la croissance</span>（增长）、<span class=\"fr\" data-fr=\"un investissement\">un investissement</span>（投资）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t22 再看一遍例句。","src":"vocab.html#t22","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 立场文结构与论点库","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：研读考试页写作模板与 50 个高分句式。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5003","level":"B2","skill":"reading","prompt":"研读高分句式时，最有用的做法是？","options":["替换关键词造自己的句子","整句背诵十遍","只记句式名称"],"answer":"替换关键词造自己的句子","explain":"套用句式并替换内容，才能把句式变成自己的表达。","source":"写作 · 句式积累"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:人工智能"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"indéniable\">indéniable</span>（不可否认的）、<span class=\"fr\" data-fr=\"une solution\">une solution</span>（解决方案）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t22","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#expressions-b2，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#expressions-b2","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:论述"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「B2 高频固定搭配」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 立场文结构与论点库","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词立场文（引言、2 个论点、反方段、结论）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5002","level":"B2","skill":"writing","prompt":"300 词立场文里反方段的作用是？","options":["承认反方合理之处并反驳","凑字数","表达个人情绪"],"answer":"承认反方合理之处并反驳","explain":"反方段展示论证的完整性与客观性，是 B2 评分的重要观察点。","source":"写作 · 论述结构"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:禁用手机"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#expressions-b2，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#expressions-b2","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:论述"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「B2 高频固定搭配」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"indéniable\">indéniable</span>（不可否认的）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 立场文结构与论点库","type":"review","steps":[{"type":"review","title":"本周回顾：B2 论述入门：立场文结构与论点库","body":"这一周围绕「B2 论述入门：立场文结构与论点库」展开：语法主线是 B2 高频固定搭配，词汇主线是 经济与金融。先用 3 句话口头复述本周学了什么，再打开日历页第 42 周清单逐条核对里程碑。","src":"calendar.html#wk-42","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"review","title":"语法复盘：B2 高频固定搭配","body":"从 grammar-b1b2.html#expressions-b2 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#expressions-b2","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:论述"}]},{"type":"review","title":"词汇自测：经济与金融","body":"遮住中文看 vocab.html#t22 的 6 个核心词：<span class=\"fr\" data-fr=\"indéniable\">indéniable</span> <span class=\"fr\" data-fr=\"une solution\">une solution</span> <span class=\"fr\" data-fr=\"un enjeu\">un enjeu</span> <span class=\"fr\" data-fr=\"un marché\">un marché</span> <span class=\"fr\" data-fr=\"la croissance\">la croissance</span> <span class=\"fr\" data-fr=\"un investissement\">un investissement</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t22","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5007","level":"B2","skill":"vocab","prompt":"« un marché » 的意思是？","options":["市场","走路的动作","三月"],"answer":"市场","explain":"marché 是市场；marche 是走路；mars 是三月。","source":"词汇 · 经济"},{"id":"q-vocab-b2-5008","level":"B2","skill":"vocab","prompt":"« un investissement » 的意思是？","options":["投资","调查","发明"],"answer":"投资","explain":"investissement 是投资；enquête 是调查；invention 是发明。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d35","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5004","level":"B2","skill":"listening","prompt":"辩论中 « en d'autres termes » 的作用是？","options":["换一种说法重申观点","引出反驳","总结全文"],"answer":"换一种说法重申观点","explain":"这个短语用于换一种表达重申，帮助听众理解。","source":"口语 · 辩论"},{"id":"q-read-b2-5004","level":"B2","skill":"reading","prompt":"B2 立场文的语域要求是？","options":["全文保持正式书面语","可以口语书面混杂","越长越正式"],"answer":"全文保持正式书面语","explain":"混用语域是 B2 写作的常见失分点。","source":"写作 · 语域"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 B2 高频固定搭配 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#expressions-b2 再核对一次。","src":"grammar-b1b2.html#mer-cequi-cest","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5007","level":"B2","skill":"grammar","prompt":"下列哪句适合正式论述？","options":["On peut soutenir que cette réforme est nécessaire.","Je crois que c'est bien.","Franchement, c'est top."],"answer":"On peut soutenir que cette réforme est nécessaire.","explain":"on peut soutenir que 是客观化的论述结构，后两句偏口语。","source":"语法 · 书面语体"},{"id":"q-gram-b2-5008","level":"B2","skill":"grammar","prompt":"「不可否认，远程办公改变了企业」应说？","options":["Il est indéniable que le télétravail a changé les entreprises.","Il est indéniable que le télétravail change les entreprises hier.","Indéniable le télétravail change."],"answer":"Il est indéniable que le télétravail a changé les entreprises.","explain":"无人称结构 il est indéniable que 后接完整从句，已完成的变化用复合过去时。","source":"语法 · 书面语体"},{"ref":"bank:grammar:B2:论述"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":43,"level":"B2","theme":"虚拟式过去时与过去假设","days":[{"day":1,"theme":"词汇 · 情感与态度","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：情感与态度","body":"本周词汇主战场是情感与态度（Les émotions et les attitudes）。先到 vocab.html#t18 把词表扫一遍，把 <span class=\"fr\" data-fr=\"regretter\">regretter</span>（后悔）、<span class=\"fr\" data-fr=\"un regret\">un regret</span>（遗憾）、<span class=\"fr\" data-fr=\"reprocher\">reprocher</span>（责备）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t18","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5009","level":"B2","skill":"vocab","prompt":"« regretter » 的意思是？","options":["后悔","欢迎","通知"],"answer":"后悔","explain":"regretter 是后悔、遗憾；souhaiter la bienvenue 是欢迎；informer 是通知。","source":"词汇 · 情感"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"vocab","title":"搭配与辨析：dommage / si seulement","body":"把 <span class=\"fr\" data-fr=\"dommage\">dommage</span>（可惜）和 <span class=\"fr\" data-fr=\"si seulement\">si seulement</span>（要是……就好了）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t18","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5010","level":"B2","skill":"vocab","prompt":"« reprocher » 的意思是？","options":["责备","使靠近","重复"],"answer":"责备","explain":"reprocher 是责备、指责；rapprocher 是使靠近；répéter 是重复。","source":"词汇 · 情感"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"listen","title":"听音辨词：情感与态度","body":"打开 对话页的 d37 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un choix\">un choix</span>（选择）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d37","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je regrette que tu sois parti si tôt.\">Je regrette que tu sois parti si tôt.</span>（我后悔你那么早离开。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：情感与态度 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"regretter\">regretter</span> <span class=\"fr\" data-fr=\"un regret\">un regret</span> <span class=\"fr\" data-fr=\"reprocher\">reprocher</span> <span class=\"fr\" data-fr=\"dommage\">dommage</span> <span class=\"fr\" data-fr=\"si seulement\">si seulement</span> <span class=\"fr\" data-fr=\"un choix\">un choix</span>。说不出来的词立刻回到 vocab.html#t18 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t18","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]}]},{"day":2,"theme":"语法 · 虚拟式过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：虚拟式过去时","body":"【虚拟式过去时】虚拟式过去时由助动词的虚拟式（aie / sois）加过去分词构成：que j'aie fait、que je sois allé。它用于表达对已发生事情的遗憾、情绪或判断：je regrette que tu sois parti。条件式过去时（j'aurais fait）则用于未实现的过去假设与遗憾、责备。 例句：<span class=\"fr\" data-fr=\"Je regrette que tu sois parti si tôt.\">Je regrette que tu sois parti si tôt.</span>（我后悔你那么早离开。）；<span class=\"fr\" data-fr=\"Si j'avais su, je serais venu plus tôt.\">Si j'avais su, je serais venu plus tôt.</span>（要是我早知道，就会早点来。）。对照 grammar-b1b2.html#subj-passe 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#subj-passe","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5009","level":"B2","skill":"grammar","prompt":"「我后悔你那么早离开」中「离开」应该用？","options":["虚拟式过去时 sois parti","虚拟式现在时 partes","条件式过去时 serais parti"],"answer":"虚拟式过去时 sois parti","explain":"regretter que 表达对已发生事情的遗憾，从句用虚拟式过去时。","source":"语法 · 虚拟式过去时"},{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 虚拟式过去时 的规则和两个例句，再打开 grammar-b1b2.html#subj-passe 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#subj-passe","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5010","level":"B2","skill":"grammar","prompt":"「要是我早知道」应说？","options":["Si j'avais su","Si je saurais","Si j'ai su"],"answer":"Si j'avais su","explain":"第三型假设的从句用愈过去时，主句用条件式过去时。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"read","title":"在短文里找虚拟式过去时","body":"在 grammar-b1b2.html#subj-passe 的例句和章末小测里挑 5 句，圈出所有属于「虚拟式过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#subj-passe","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je regrette que tu sois parti si tôt.\">Je regrette que tu sois parti si tôt.</span>（我后悔你那么早离开。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，虚拟式过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：条件式过去时","body":"今天再回 grammar-b1b2.html#cond-passe 看一遍 条件式过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#cond-passe","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:虚拟式过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d37 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d37 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d37","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5005","level":"B2","skill":"listening","prompt":"听到 /ʒə ʁəɡʁɛt kə ty swa paʁti/ 中 swa 的形式是？","options":["虚拟式过去时的助动词","直陈式现在时","简单将来时"],"answer":"虚拟式过去时的助动词","explain":"sois parti 由虚拟式助动词加过去分词构成虚拟式过去时。","source":"语法 · 虚拟式过去时"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:自行车道"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听访谈中的遗憾与评价句，判断虚拟式用的是现在时还是过去时。","src":"dialogue.html#d37","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"regretter\">regretter</span>（后悔）、<span class=\"fr\" data-fr=\"un regret\">un regret</span>（遗憾）、<span class=\"fr\" data-fr=\"reprocher\">reprocher</span>（责备）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t18","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「虚拟式过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d37","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 虚拟式过去时与过去假设","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就「如果能重来」做 5 分钟表达，混合虚拟式过去时与条件式过去时。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5003","level":"B2","skill":"speaking","prompt":"表达「如果能重来」时，最自然的组合是？","options":["si 加愈过去时、主句条件式过去时","si 加现在时、主句将来时","si 加未完成过去时、主句现在时"],"answer":"si 加愈过去时、主句条件式过去时","explain":"谈论无法改变的过去要用第三型假设。","source":"语法 · 假设三型"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:心理健康"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d37 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、虚拟式过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d37","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"dommage\">dommage</span>（可惜）、<span class=\"fr\" data-fr=\"si seulement\">si seulement</span>（要是……就好了）、<span class=\"fr\" data-fr=\"un choix\">un choix</span>（选择）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t18 再看一遍例句。","src":"vocab.html#t18","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 虚拟式过去时与过去假设","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页虚拟式过去时章节与现在时对比表。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5005","level":"B2","skill":"reading","prompt":"« j'aurais dû » 的意思是？","options":["我本应该","我应该","我将会应该"],"answer":"我本应该","explain":"条件式过去时可以表达对过去的遗憾或责备：j'aurais dû 表示「我本应该」。","source":"语法 · 条件式过去时"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:过度旅游"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「虚拟式过去时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"regretter\">regretter</span>（后悔）、<span class=\"fr\" data-fr=\"un regret\">un regret</span>（遗憾）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t18","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#subj-passe，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#subj-passe","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「虚拟式过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 虚拟式过去时与过去假设","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 250 词反思文，含 4 个虚拟式过去时。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5003","level":"B2","skill":"writing","prompt":"反思文里表达「可惜我没能来」应说？","options":["Dommage que je n'aie pas pu venir.","Dommage que je ne peux pas venir.","Dommage je n'ai pas pu venir."],"answer":"Dommage que je n'aie pas pu venir.","explain":"dommage que 后接虚拟式，谈论已发生的事用虚拟式过去时，que 不能省。","source":"语法 · 虚拟式过去时"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:四天工作制"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#subj-passe，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#subj-passe","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「虚拟式过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"regretter\">regretter</span>（后悔）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 虚拟式过去时与过去假设","type":"review","steps":[{"type":"review","title":"本周回顾：虚拟式过去时与过去假设","body":"这一周围绕「虚拟式过去时与过去假设」展开：语法主线是 虚拟式过去时，词汇主线是 情感与态度。先用 3 句话口头复述本周学了什么，再打开日历页第 43 周清单逐条核对里程碑。","src":"calendar.html#wk-43","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"语法复盘：虚拟式过去时","body":"从 grammar-b1b2.html#subj-passe 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#subj-passe","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"review","title":"词汇自测：情感与态度","body":"遮住中文看 vocab.html#t18 的 6 个核心词：<span class=\"fr\" data-fr=\"regretter\">regretter</span> <span class=\"fr\" data-fr=\"un regret\">un regret</span> <span class=\"fr\" data-fr=\"reprocher\">reprocher</span> <span class=\"fr\" data-fr=\"dommage\">dommage</span> <span class=\"fr\" data-fr=\"si seulement\">si seulement</span> <span class=\"fr\" data-fr=\"un choix\">un choix</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t18","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5011","level":"B2","skill":"vocab","prompt":"« un regret » 的意思是？","options":["遗憾","登记","问候"],"answer":"遗憾","explain":"regret 是遗憾；enregistrement 是登记；salutation 是问候。","source":"词汇 · 情感"},{"id":"q-vocab-b2-5012","level":"B2","skill":"vocab","prompt":"« un choix » 的意思是？","options":["选择","声音","原因"],"answer":"选择","explain":"choix 是选择；voix 是声音；cause 是原因。","source":"词汇 · 情感"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d37","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5006","level":"B2","skill":"listening","prompt":"听到 « si seulement j'avais su » 时表示？","options":["表达强烈遗憾","提出可实现的条件","表达未来的愿望"],"answer":"表达强烈遗憾","explain":"si seulement 加愈过去时表达对过去的强烈遗憾。","source":"语法 · 假设与遗憾"},{"id":"q-read-b2-5006","level":"B2","skill":"reading","prompt":"虚拟式过去时的构成是？","options":["虚拟式助动词加过去分词","现在时助动词加过去分词","将来时助动词加过去分词"],"answer":"虚拟式助动词加过去分词","explain":"aie / sois / ait / ayons / ayez / aient 加过去分词构成虚拟式过去时。","source":"语法 · 虚拟式过去时"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 虚拟式过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#subj-passe 再核对一次。","src":"grammar-b1b2.html#cond-passe","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5011","level":"B2","skill":"grammar","prompt":"« Je suis désolé que vous ___ attendu si longtemps. »（avoir）","options":["ayez","avez","aurez"],"answer":"ayez","explain":"主句表达情感，从句用虚拟式；已发生的事用虚拟式过去时 ayez attendu。","source":"语法 · 虚拟式过去时"},{"id":"q-gram-b2-5012","level":"B2","skill":"grammar","prompt":"下列哪句表达「对过去的责备」？","options":["Tu aurais pu me prévenir.","Tu peux me prévenir.","Tu pourras me prévenir."],"answer":"Tu aurais pu me prévenir.","explain":"条件式过去时用于对过去行为的责备或遗憾。","source":"语法 · 条件式过去时"},{"ref":"bank:grammar:B2:虚拟式过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":44,"level":"B2","theme":"环境、政治与法律长文与辩论","days":[{"day":1,"theme":"词汇 · 环境与生态","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：环境与生态","body":"环境与生态（L'environnement et l'écologie）是这一周要反复见面的主题域。打开 vocab.html#t20，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"une loi\">une loi</span>（法律）、<span class=\"fr\" data-fr=\"un tribunal\">un tribunal</span>（法院）、<span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span>（公民）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t20","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5013","level":"B2","skill":"vocab","prompt":"« une réforme » 的意思是？","options":["改革","形式","轮廓"],"answer":"改革","explain":"réforme 是改革；forme 是形式，也可指轮廓。","source":"词汇 · 政治"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"vocab","title":"搭配与辨析：une réforme / un obstacle","body":"<span class=\"fr\" data-fr=\"une réforme\">une réforme</span>（改革）与 <span class=\"fr\" data-fr=\"un obstacle\">un obstacle</span>（障碍）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t20","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5014","level":"B2","skill":"vocab","prompt":"« appliquer » 的意思是？","options":["适用；实施","申请","折叠"],"answer":"适用；实施","explain":"appliquer 是适用、实施；postuler 是申请；plier 是折叠。","source":"词汇 · 政治"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"listen","title":"听音辨词：环境与生态","body":"打开 对话页的 d38、d27 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"appliquer\">appliquer</span>（适用；实施）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d38","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Quoi qu'il arrive, la loi s'appliquera.\">Quoi qu'il arrive, la loi s'appliquera.</span>（无论发生什么，法律都会适用。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：环境与生态 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"une loi\">une loi</span> <span class=\"fr\" data-fr=\"un tribunal\">un tribunal</span> <span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span> <span class=\"fr\" data-fr=\"une réforme\">une réforme</span> <span class=\"fr\" data-fr=\"un obstacle\">un obstacle</span> <span class=\"fr\" data-fr=\"appliquer\">appliquer</span>。说不出来的词立刻回到 vocab.html#t20 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t20","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]}]},{"day":2,"theme":"语法 · 虚拟式连词清单","type":"grammar","steps":[{"type":"grammar","title":"语法点：虚拟式连词清单","body":"【虚拟式连词清单】高级让步结构包括 quoi que、où que、quel que soit、si… que 加虚拟式。quel que 要与后面主语的性数配合（quels que soient les obstacles），这是最容易失分的地方；si… que 表示「无论多么」，从句用虚拟式且不加 ne。 例句：<span class=\"fr\" data-fr=\"Quoi qu'il arrive, la loi s'appliquera.\">Quoi qu'il arrive, la loi s'appliquera.</span>（无论发生什么，法律都会适用。）；<span class=\"fr\" data-fr=\"Quels que soient les obstacles, le projet continue.\">Quels que soient les obstacles, le projet continue.</span>（无论有什么障碍，项目都会继续。）。对照 grammar-b1b2.html#subj-conjonctions 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#subj-conjonctions","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5013","level":"B2","skill":"grammar","prompt":"« ___ il arrive, la loi s'appliquera. »","options":["Quoi qu'","Quoique","Bien que"],"answer":"Quoi qu'","explain":"quoi que 表示无论什么，que 后接虚拟式从句。","source":"语法 · 让步"},{"ref":"bank:grammar:B2:让步"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-b1b2.html#subj-conjonctions 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Quoi qu'il arrive, la loi s'appliquera.\">Quoi qu'il arrive, la loi s'appliquera.</span>（无论发生什么，法律都会适用。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-b1b2.html#subj-conjonctions","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5014","level":"B2","skill":"grammar","prompt":"« ___ soient les obstacles, le projet continue. »","options":["Quels que","Quel que","Quoique"],"answer":"Quels que","explain":"quel que 要与主语性数配合，obstacles 是阳性复数，用 quels que。","source":"语法 · 让步"},{"ref":"bank:grammar:B2:让步"}]},{"type":"read","title":"在短文里找虚拟式连词清单","body":"在 grammar-b1b2.html#subj-conjonctions 的例句和章末小测里挑 5 句，圈出所有属于「虚拟式连词清单」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#subj-conjonctions","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Quoi qu'il arrive, la loi s'appliquera.\">Quoi qu'il arrive, la loi s'appliquera.</span>（无论发生什么，法律都会适用。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，虚拟式连词清单 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：让步 concession","body":"今天再回 grammar-b1b2.html#conn-concession 看一遍 让步 concession，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#conn-concession","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:让步"}]}]},{"day":3,"theme":"精听 · 对话页的 d38、d27 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d38、d27 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d38","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5007","level":"B2","skill":"listening","prompt":"正式辩论中记录反驳点最有效的符号是？","options":["用箭头标出「对方说…但是…」","只记关键词","只记数字"],"answer":"用箭头标出「对方说…但是…」","explain":"用箭头表示反驳关系，能快速还原辩论的逻辑结构。","source":"考试 · 听力策略"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:四天工作制"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一场正式辩论，记录每位发言人的核心主张与反驳点。","src":"dialogue.html#d38","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"une loi\">une loi</span>（法律）、<span class=\"fr\" data-fr=\"un tribunal\">un tribunal</span>（法院）、<span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span>（公民）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t20","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「虚拟式连词清单 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d38","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 环境、政治与法律长文与辩论","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：模拟辩论：抽签决定正反方，各陈述 4 分钟加交叉质问 3 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5004","level":"B2","skill":"speaking","prompt":"交叉质问他人的观点时，最专业的做法是？","options":["先复述对方观点再提问","直接打断","否定对方人格"],"answer":"先复述对方观点再提问","explain":"复述对方观点能确认理解一致，再提问才显得专业。","source":"口语 · 辩论"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:禁止私家车"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d38、d27 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、虚拟式连词清单 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d38","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une réforme\">une réforme</span>（改革）、<span class=\"fr\" data-fr=\"un obstacle\">un obstacle</span>（障碍）、<span class=\"fr\" data-fr=\"appliquer\">appliquer</span>（适用；实施）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t20 再看一遍例句。","src":"vocab.html#t20","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 环境、政治与法律长文与辩论","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读 2 篇 1200 词长文（气候政策、法律议题），边读边做笔记。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5007","level":"B2","skill":"reading","prompt":"读法律议题长文时，最需要标注的是？","options":["主体、义务与例外","生词数量","段落长度"],"answer":"主体、义务与例外","explain":"法律类文本的核心是「谁必须做什么、有哪些例外」。","source":"考试 · 阅读策略"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:一次性塑料"},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"une loi\">une loi</span>（法律）、<span class=\"fr\" data-fr=\"un tribunal\">un tribunal</span>（法院）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t20","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#subj-conjonctions，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#subj-conjonctions","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:让步"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「虚拟式连词清单」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 环境、政治与法律长文与辩论","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词社论（立场鲜明，含 2 处让步）。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5004","level":"B2","skill":"writing","prompt":"社论里让步的作用是？","options":["展示论证的客观与完整","降低立场强度","凑字数"],"answer":"展示论证的客观与完整","explain":"社论立场鲜明，但加入让步能让论证显得克制而有力量。","source":"写作 · 社论"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:免费停车"},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#subj-conjonctions，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#subj-conjonctions","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:让步"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「虚拟式连词清单」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"une loi\">une loi</span>（法律）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 环境、政治与法律长文与辩论","type":"review","steps":[{"type":"review","title":"本周回顾：环境、政治与法律长文与辩论","body":"这一周围绕「环境、政治与法律长文与辩论」展开：语法主线是 虚拟式连词清单，词汇主线是 环境与生态。先用 3 句话口头复述本周学了什么，再打开日历页第 44 周清单逐条核对里程碑。","src":"calendar.html#wk-44","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"review","title":"语法复盘：虚拟式连词清单","body":"从 grammar-b1b2.html#subj-conjonctions 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#subj-conjonctions","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:让步"}]},{"type":"review","title":"词汇自测：环境与生态","body":"遮住中文看 vocab.html#t20 的 6 个核心词：<span class=\"fr\" data-fr=\"une loi\">une loi</span> <span class=\"fr\" data-fr=\"un tribunal\">un tribunal</span> <span class=\"fr\" data-fr=\"un citoyen\">un citoyen</span> <span class=\"fr\" data-fr=\"une réforme\">une réforme</span> <span class=\"fr\" data-fr=\"un obstacle\">un obstacle</span> <span class=\"fr\" data-fr=\"appliquer\">appliquer</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t20","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5015","level":"B2","skill":"vocab","prompt":"« un obstacle » 的意思是？","options":["障碍","观察","反对者"],"answer":"障碍","explain":"obstacle 是障碍；observation 是观察；opposant 是反对者。","source":"词汇 · 抽象概念"},{"id":"q-vocab-b2-5016","level":"B2","skill":"vocab","prompt":"« un tribunal » 的意思是？","options":["法院","审判者","法庭记录"],"answer":"法院","explain":"tribunal 指法院；juge 是法官。","source":"词汇 · 法律"},{"ref":"bank:vocab:A2:环境与生态"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d38","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5008","level":"B2","skill":"listening","prompt":"辩论中 « je vous suis sur ce point, cependant… » 表示？","options":["部分同意后转折","完全同意","完全反对"],"answer":"部分同意后转折","explain":"先表示认同再转折，是高级辩论里的礼貌转折结构。","source":"口语 · 辩论"},{"id":"q-read-b2-5008","level":"B2","skill":"reading","prompt":"« quel que soit » 的配合规则是？","options":["与后面主语的性数配合","永远用 quel","永远用 quelle"],"answer":"与后面主语的性数配合","explain":"quel 要与主语性数一致：quel que soit le problème、quelles que soient les raisons。","source":"语法 · 让步"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 虚拟式连词清单 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#subj-conjonctions 再核对一次。","src":"grammar-b1b2.html#conn-concession","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5015","level":"B2","skill":"grammar","prompt":"「无论多么困难」应说？","options":["si difficile que ce soit","si difficile que c'est","si difficile qu'il est"],"answer":"si difficile que ce soit","explain":"si 加形容词加 que 表示「无论多么」，从句用虚拟式，且不加 ne。","source":"语法 · 让步"},{"id":"q-gram-b2-5016","level":"B2","skill":"grammar","prompt":"「尽管他很努力，他还是失败了」应说？","options":["Bien qu'il ait travaillé dur, il a échoué.","Bien qu'il a travaillé dur, il a échoué.","Malgré qu'il ait travaillé dur, il a échoué."],"answer":"Bien qu'il ait travaillé dur, il a échoué.","explain":"bien que 后接虚拟式；malgré 是介词，不能直接接 que 从句。","source":"语法 · 让步"},{"ref":"bank:grammar:B2:让步"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]},{"week":45,"level":"B2","theme":"条件式过去时与三种假设的高级用法","days":[{"day":1,"theme":"词汇 · 经济与金融","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：经济与金融","body":"本周词汇主战场是经济与金融（L'économie et la finance）。先到 vocab.html#t22 把词表扫一遍，把 <span class=\"fr\" data-fr=\"un risque\">un risque</span>（风险）、<span class=\"fr\" data-fr=\"une décision\">une décision</span>（决定）、<span class=\"fr\" data-fr=\"investir\">investir</span>（投资）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t22","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-b2-5017","level":"B2","skill":"vocab","prompt":"« un risque » 的意思是？","options":["风险","财富","田地"],"answer":"风险","explain":"risque 是风险；richesse 是财富；champ 是田地。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"vocab","title":"搭配与辨析：une perte / éviter","body":"把 <span class=\"fr\" data-fr=\"une perte\">une perte</span>（损失）和 <span class=\"fr\" data-fr=\"éviter\">éviter</span>（避免）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t22","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-b2-5018","level":"B2","skill":"vocab","prompt":"« prévoir » 的意思是？","options":["预见","提供","阻止"],"answer":"预见","explain":"prévoir 是预见、计划；pourvoir 是提供；prévenir 是通知或预防。","source":"词汇 · 经济"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"listen","title":"听音辨词：经济与金融","body":"打开 对话页的 d38 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"prévoir\">prévoir</span>（预见）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d38","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.\">Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.</span>（要是我当时听了你的建议，今天就不会这么紧张。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"vocab","title":"日终自测：经济与金融 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un risque\">un risque</span> <span class=\"fr\" data-fr=\"une décision\">une décision</span> <span class=\"fr\" data-fr=\"investir\">investir</span> <span class=\"fr\" data-fr=\"une perte\">une perte</span> <span class=\"fr\" data-fr=\"éviter\">éviter</span> <span class=\"fr\" data-fr=\"prévoir\">prévoir</span>。说不出来的词立刻回到 vocab.html#t22 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t22","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]}]},{"day":2,"theme":"语法 · 条件式过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：条件式过去时","body":"【条件式过去时】条件式过去时有两式：常用式 j'aurais fait 与文学式 j'eusse fait，后者只需能识别。混合假设有两组常见搭配：si 加愈过去时配条件式现在时（过去条件、现在结果），以及 si 加未完成过去时配条件式过去时（现在条件、过去结果）。条件式过去时还用于表达遗憾与责备。 例句：<span class=\"fr\" data-fr=\"Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.\">Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.</span>（要是我当时听了你的建议，今天就不会这么紧张。）；<span class=\"fr\" data-fr=\"J'aurais dû investir plus tôt.\">J'aurais dû investir plus tôt.</span>（我本应该早点投资。）。对照 grammar-b1b2.html#cond-passe 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#cond-passe","hint":"先读规则再看例句","quiz":[{"id":"q-gram-b2-5017","level":"B2","skill":"grammar","prompt":"「要是我当时听了你的建议」应说？","options":["Si j'avais suivi tes conseils","Si je suivais tes conseils","Si j'aurais suivi tes conseils"],"answer":"Si j'avais suivi tes conseils","explain":"第三型假设的 si 从句用愈过去时，绝不能用条件式。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 条件式过去时 的规则和两个例句，再打开 grammar-b1b2.html#cond-passe 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#cond-passe","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-b2-5018","level":"B2","skill":"grammar","prompt":"「我本应该早点投资」应说？","options":["J'aurais dû investir plus tôt.","J'ai dû investir plus tôt.","Je devrais investir plus tôt."],"answer":"J'aurais dû investir plus tôt.","explain":"条件式过去时可以表达对过去的遗憾与自我责备。","source":"语法 · 条件式过去时"},{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"read","title":"在短文里找条件式过去时","body":"在 grammar-b1b2.html#cond-passe 的例句和章末小测里挑 5 句，圈出所有属于「条件式过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#cond-passe","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.\">Si j'avais suivi tes conseils, je serais moins stressé aujourd'hui.</span>（要是我当时听了你的建议，今天就不会这么紧张。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，条件式过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"语法点巩固：si 的三种假设句型","body":"今天再回 grammar-b1b2.html#si-trois 看一遍 si 的三种假设句型，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#si-trois","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:B2:条件式过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d38 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d38 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d38","hint":"不暂停、不看文本","quiz":[{"id":"q-list-b2-5009","level":"B2","skill":"listening","prompt":"反事实论证的标志性结构是？","options":["si 加愈过去时，主句条件式过去时","si 加现在时，主句将来时","parce que 加原因"],"answer":"si 加愈过去时，主句条件式过去时","explain":"反事实论证讨论与事实相反的过去，使用第三型假设。","source":"语法 · 假设三型"},{"ref":"bank:listening:B2:听力"}],"exam":"exam:listening:B2:一次性塑料"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听辩论中的反事实论证（如果当年那样做）。","src":"dialogue.html#d38","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un risque\">un risque</span>（风险）、<span class=\"fr\" data-fr=\"une décision\">une décision</span>（决定）、<span class=\"fr\" data-fr=\"investir\">investir</span>（投资）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t22","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「条件式过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d38","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:B2:听力"}]}]},{"day":4,"theme":"口语 · 条件式过去时与三种假设的高级用法","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就一个历史或政策决策做 4 分钟反事实分析。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-b2-5005","level":"B2","skill":"speaking","prompt":"做反事实分析时，最清晰的框架是？","options":["当年做了什么、结果如何、若改变会怎样","只讲结果","只讲现状"],"answer":"当年做了什么、结果如何、若改变会怎样","explain":"反事实分析需要先交代事实，再提出假设并推出后果。","source":"口语 · 论述结构"},{"ref":"bank:speaking:B2:口语"}],"exam":"exam:speaking:B2:远程办公"},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:B2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d38 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、条件式过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d38","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:B2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une perte\">une perte</span>（损失）、<span class=\"fr\" data-fr=\"éviter\">éviter</span>（避免）、<span class=\"fr\" data-fr=\"prévoir\">prévoir</span>（预见）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t22 再看一遍例句。","src":"vocab.html#t22","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":5,"theme":"精读 · 条件式过去时与三种假设的高级用法","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页假设三型与条件式过去时章节。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-b2-5009","level":"B2","skill":"reading","prompt":"« j'eusse fait » 属于？","options":["文学式的条件式过去时第二形式","简单过去时","虚拟式现在时"],"answer":"文学式的条件式过去时第二形式","explain":"j'eusse fait 是条件式过去时的文学式，阅读中只需识别，不必主动使用。","source":"语法 · 条件式过去时"},{"ref":"bank:reading:B2:阅读"}],"exam":"exam:reading:B2:远程办公"},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「条件式过去时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un risque\">un risque</span>（风险）、<span class=\"fr\" data-fr=\"une décision\">une décision</span>（决定）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t22","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#cond-passe，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#cond-passe","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「条件式过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:B2:写作"}]}]},{"day":6,"theme":"写作 · 条件式过去时与三种假设的高级用法","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 300 词「假如……今天会怎样」分析文。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-b2-5005","level":"B2","skill":"writing","prompt":"「假如当年政策不同，今天会怎样」中，主句应该用？","options":["条件式现在时","条件式过去时","简单将来时"],"answer":"条件式现在时","explain":"过去条件配现在结果属于混合假设：si 加愈过去时，主句用条件式现在时。","source":"语法 · 假设三型"},{"ref":"bank:writing:B2:写作"}],"exam":"exam:writing:B2:四天工作制"},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:B2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#cond-passe，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#cond-passe","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「条件式过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:B2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un risque\">un risque</span>（风险）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:B2:口语"}]}]},{"day":7,"theme":"复盘 · 条件式过去时与三种假设的高级用法","type":"review","steps":[{"type":"review","title":"本周回顾：条件式过去时与三种假设的高级用法","body":"这一周围绕「条件式过去时与三种假设的高级用法」展开：语法主线是 条件式过去时，词汇主线是 经济与金融。先用 3 句话口头复述本周学了什么，再打开日历页第 45 周清单逐条核对里程碑。","src":"calendar.html#wk-45","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"review","title":"语法复盘：条件式过去时","body":"从 grammar-b1b2.html#cond-passe 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#cond-passe","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"review","title":"词汇自测：经济与金融","body":"遮住中文看 vocab.html#t22 的 6 个核心词：<span class=\"fr\" data-fr=\"un risque\">un risque</span> <span class=\"fr\" data-fr=\"une décision\">une décision</span> <span class=\"fr\" data-fr=\"investir\">investir</span> <span class=\"fr\" data-fr=\"une perte\">une perte</span> <span class=\"fr\" data-fr=\"éviter\">éviter</span> <span class=\"fr\" data-fr=\"prévoir\">prévoir</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t22","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-b2-5019","level":"B2","skill":"vocab","prompt":"« une perte » 的意思是？","options":["损失","珍珠","港口"],"answer":"损失","explain":"perte 是损失；perle 是珍珠；port 是港口。","source":"词汇 · 经济"},{"id":"q-vocab-b2-5020","level":"B2","skill":"vocab","prompt":"« éviter » 的意思是？","options":["避免","参观","清空"],"answer":"避免","explain":"éviter 是避免；visiter 是参观；vider 是清空。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A2:经济与金融"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d38","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-b2-5010","level":"B2","skill":"listening","prompt":"听到 « si on avait anticipé, on n'en serait pas là » 属于？","options":["混合假设","第一型假设","纯条件句"],"answer":"混合假设","explain":"si 加愈过去时配主句条件式现在时，是典型的混合假设。","source":"语法 · 假设三型"},{"id":"q-read-b2-5010","level":"B2","skill":"reading","prompt":"条件式过去时的两式是？","options":["j'aurais fait 与 j'eusse fait","j'ai fait 与 j'avais fait","je ferais 与 je ferai"],"answer":"j'aurais fait 与 j'eusse fait","explain":"常用式为 j'aurais fait，文学式为 j'eusse fait。","source":"语法 · 条件式过去时"},{"ref":"bank:listening:B2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 条件式过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#cond-passe 再核对一次。","src":"grammar-b1b2.html#si-trois","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-b2-5019","level":"B2","skill":"grammar","prompt":"「要是当时没冒这个险，现在会怎样？」应说？","options":["Si on n'avait pas pris ce risque, où en serait-on ?","Si on n'a pas pris ce risque, où en serait-on ?","Si on ne prenait pas ce risque, où en aurait-on été ?"],"answer":"Si on n'avait pas pris ce risque, où en serait-on ?","explain":"过去条件用愈过去时，现在结果用条件式现在时，构成混合假设。","source":"语法 · 假设三型"},{"id":"q-gram-b2-5020","level":"B2","skill":"grammar","prompt":"下列哪一句不符合 si 从句的规则？","options":["Si j'aurais eu le temps, je serais venu.","Si j'avais eu le temps, je serais venu.","J'aurais dû venir plus tôt."],"answer":"Si j'aurais eu le temps, je serais venu.","explain":"si 从句里不能出现条件式；第三型假设应为 Si j'avais eu le temps。","source":"语法 · 假设三型"},{"ref":"bank:grammar:B2:条件式过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:B2:写作"}]}]}]}];
